import{_ as t,o as d,c as o,a5 as c}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"Upgrade to 2.8","description":"","frontmatter":{"title":"Upgrade to 2.8","order":2},"headers":[],"relativePath":"en/latest/tutorial/upgrade-2.8.md","filePath":"en/latest/tutorial/upgrade-2.8.md","lastUpdated":1788455378000}'),a={name:"en/latest/tutorial/upgrade-2.8.md"};function r(n,e,i,s,l,p){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="upgrade-to-2-8" tabindex="-1">Upgrade to 2.8 <a class="header-anchor" href="#upgrade-to-2-8" aria-label="Permalink to &quot;Upgrade to 2.8&quot;">​</a></h1><p>Konado 2.8 rebuilds the runtime, compiler, and plugin layout, and standardizes the public API names. Back up the project, replace the complete old plugin directories with 2.8, and reopen Godot.</p><p>The plugin migrates known plugin paths and Autoload names. Scene and resource references with UIDs normally resolve to the new locations automatically. User GDScript is never rewritten, so update old type names manually.</p><table tabindex="0"><thead><tr><th>2.7.4</th><th>2.8</th></tr></thead><tbody><tr><td><code>KND_DialogueManager</code></td><td><code>KonadoDialogueManager</code></td></tr><tr><td><code>KND_Shot</code></td><td><code>KonadoShot</code></td></tr><tr><td><code>KND_SaveSystem</code></td><td><code>KonadoSaveSystem</code></td></tr><tr><td><code>KND_SaveData</code></td><td><code>KonadoSaveData</code></td></tr><tr><td><code>KND_Settings</code></td><td><code>KonadoSettings</code></td></tr><tr><td><code>KND_SettingCategory</code></td><td><code>KonadoSettingCategory</code></td></tr><tr><td><code>KND_SettingItem</code></td><td><code>KonadoSettingItem</code></td></tr><tr><td><code>KND_SettingsUIFactory</code></td><td><code>KonadoSettingsUIFactory</code></td></tr><tr><td><code>KND_AchievementManager</code></td><td><code>KonadoAchievements</code></td></tr><tr><td><code>KND_I18n</code></td><td><code>KonadoStoryLocalization</code></td></tr><tr><td><code>KND_Background</code> / <code>KND_BackgroundList</code></td><td><code>KonadoBackground</code> / <code>KonadoBackgroundList</code></td></tr><tr><td><code>KND_Character</code> / <code>KND_CharacterList</code></td><td><code>KonadoCharacter</code> / <code>KonadoCharacterList</code></td></tr><tr><td><code>KND_CharacterSceneBase</code></td><td><code>KonadoCharacterSceneBase</code></td></tr><tr><td><code>KND_CharacterTransitionFrame</code></td><td><code>KonadoCharacterTransitionFrame</code></td></tr><tr><td><code>KND_Actor</code></td><td><code>KonadoActor</code></td></tr><tr><td><code>KND_ActingInterface</code></td><td><code>KonadoStageController</code></td></tr><tr><td><code>KND_Bgm</code> / <code>KND_BgmList</code></td><td><code>KonadoBackgroundMusic</code> / <code>KonadoBackgroundMusicList</code></td></tr><tr><td><code>DialogVoice</code> / <code>DialogVoiceList</code></td><td><code>KonadoVoice</code> / <code>KonadoVoiceList</code></td></tr><tr><td><code>KND_SoundEffect</code> / <code>KND_SoundEffectList</code></td><td><code>KonadoSoundEffect</code> / <code>KonadoSoundEffectList</code></td></tr><tr><td><code>KND_AudioInterface</code></td><td><code>KonadoAudioController</code></td></tr><tr><td><code>KND_DialogueBox</code></td><td><code>KonadoDialogueBox</code></td></tr><tr><td><code>KND_Dialogue</code> / <code>KND_DialogueChoice</code></td><td>Read-only <code>KonadoInstruction</code></td></tr><tr><td><code>KND_ScreenText</code></td><td><code>KonadoScreenText</code></td></tr><tr><td><code>KND_TypewriterText</code></td><td><code>KonadoTypewriterText</code></td></tr><tr><td><code>KND_Data</code></td><td><code>KonadoData</code></td></tr><tr><td><code>KND_VariableStore</code></td><td><code>KonadoVariableStore</code></td></tr><tr><td><code>KND_BackgroundSceneBase</code></td><td><code>KonadoBackgroundSceneBase</code></td></tr><tr><td><code>KND_ActorMotionLayer</code></td><td><code>KonadoActorMotionLayer</code></td></tr><tr><td><code>KonadoCamera2D</code></td><td><code>KonadoCameraMarker</code></td></tr><tr><td><code>KND_Logger</code></td><td><code>KonadoLogger</code></td></tr></tbody></table><p>Update old plugin paths that are stored as literal strings. Ordinary scene references that resolve through their UID do not need manual changes.</p><p>The old <code>KND_CharacterStatus</code> resource is replaced by the character-scene status protocol and <code>status_aliases</code>. Do not instantiate <code>KND_BackgroundTransitionLayer</code>; <code>KonadoStageController</code> now owns background transitions internally. Tools that used <code>KonadoScriptsInterpreter</code> directly should compile a <code>KonadoProgram</code> with <code>KonadoScriptCompiler</code> and play it through <code>KonadoDialogueManager</code>.</p><p>Godot reimports <code>.ks</code> source with the 2.8 compiler; do not copy generated 2.7 compiler caches. Version 2.7 saves cannot be restored by 2.8 and are rejected explicitly. An unquoted dialogue speaker is an actor ID in 2.8; quote the speaker when it is a text label.</p><p>After upgrading, verify that the project has no GDScript parse errors, reimport every <code>.ks</code> file, and test startup, cross-script jumps, save/load, and locale switching.</p>',8)])])}const g=t(a,[["render",r]]);export{u as __pageData,g as default};
